const express = require('express');
const crypto = require('crypto');
const app = express();

// Multi-tenant email service with role-based access
const tenants = new Map();
const sessions = new Map();

class TenantContext {
  constructor(tenantId, quotaLimit) {
    this.tenantId = tenantId;
    this.quotaLimit = quotaLimit;
    this.sentCount = 0;
    this.users = new Map();
    this.templates = new Map();
  }

  addUser(userId, role, email) {
    this.users.set(userId, { role, email, tenantId: this.tenantId });
  }

  getUser(userId) {
    return this.users.get(userId);
  }
}

// Initialize demo tenants
const tenantA = new TenantContext('tenant-a', 1000);
tenantA.addUser('admin-a', 'admin', 'admin@tenant-a.com');
tenantA.addUser('user-a', 'member', 'user@tenant-a.com');
tenantA.templates.set('welcome', { subject: 'Welcome!', body: 'Hello {{name}}' });
tenants.set('tenant-a', tenantA);

const tenantB = new TenantContext('tenant-b', 500);
tenantB.addUser('admin-b', 'admin', 'admin@tenant-b.com');
tenantB.addUser('user-b', 'member', 'user@tenant-b.com');
tenantB.templates.set('invoice', { subject: 'Invoice', body: 'Amount: {{amount}}' });
tenants.set('tenant-b', tenantB);

app.use(express.json());

// Authentication middleware
function authenticate(req, res, next) {
  const token = req.headers['x-session-token'];
  if (!token || !sessions.has(token)) {
    return res.status(401).json({ error: 'Unauthorized' });
  }
  req.session = sessions.get(token);
  next();
}

// Authorization resolver - determines effective permissions
function resolvePermissions(session, targetTenantId) {
  const { userId, tenantId } = session;
  const tenant = tenants.get(tenantId);
  if (!tenant) return { authorized: false };

  const user = tenant.getUser(userId);
  if (!user) return { authorized: false };

  // Build permission context
  const permCtx = {
    authorized: true,
    role: user.role,
    sourceTenant: tenantId,
    effectiveTenant: targetTenantId || tenantId,
    canSendEmail: user.role === 'admin' || user.role === 'member',
    canSendBulk: user.role === 'admin',
    canManageTemplates: user.role === 'admin'
  };

  return permCtx;
}

// Tenant isolation check
function enforceTenantBoundary(permCtx) {
  // Verify the operation stays within tenant boundary
  return permCtx.sourceTenant === permCtx.effectiveTenant;
}

// Email sending endpoint
app.post('/api/email/send', authenticate, (req, res) => {
  const { to, subject, body, templateId, tenantScope } = req.body;

  const permissions = resolvePermissions(req.session, tenantScope);
  if (!permissions.authorized || !permissions.canSendEmail) {
    return res.status(403).json({ error: 'Forbidden' });
  }

  // Enforce tenant isolation
  if (!enforceTenantBoundary(permissions)) {
    return res.status(403).json({ error: 'Cross-tenant access denied' });
  }

  const tenant = tenants.get(permissions.effectiveTenant);
  if (tenant.sentCount >= tenant.quotaLimit) {
    return res.status(429).json({ error: 'Quota exceeded' });
  }

  let emailSubject = subject;
  let emailBody = body;

  if (templateId) {
    const template = tenant.templates.get(templateId);
    if (!template) {
      return res.status(404).json({ error: 'Template not found' });
    }
    emailSubject = template.subject;
    emailBody = template.body;
  }

  tenant.sentCount++;
  res.json({ success: true, messageId: crypto.randomUUID() });
});

// Bulk email endpoint - admin only
app.post('/api/email/bulk', authenticate, (req, res) => {
  const { recipients, templateId, tenantScope } = req.body;

  const permissions = resolvePermissions(req.session, tenantScope);
  if (!permissions.authorized || !permissions.canSendBulk) {
    return res.status(403).json({ error: 'Forbidden: admin required' });
  }

  if (!enforceTenantBoundary(permissions)) {
    return res.status(403).json({ error: 'Cross-tenant access denied' });
  }

  const tenant = tenants.get(permissions.effectiveTenant);
  const template = tenant.templates.get(templateId);
  if (!template) {
    return res.status(404).json({ error: 'Template not found' });
  }

  // Process bulk send
  const results = recipients.map(r => ({
    to: r, messageId: crypto.randomUUID(), status: 'queued'
  }));
  tenant.sentCount += recipients.length;
  res.json({ success: true, results });
});

// Template management - admin only
app.post('/api/templates', authenticate, (req, res) => {
  const { templateId, subject, body, tenantScope } = req.body;

  const permissions = resolvePermissions(req.session, tenantScope);
  if (!permissions.authorized || !permissions.canManageTemplates) {
    return res.status(403).json({ error: 'Forbidden: admin required' });
  }

  if (!enforceTenantBoundary(permissions)) {
    return res.status(403).json({ error: 'Cross-tenant access denied' });
  }

  const tenant = tenants.get(permissions.effectiveTenant);
  tenant.templates.set(templateId, { subject, body });
  res.json({ success: true });
});

// Login endpoint
app.post('/api/login', (req, res) => {
  const { userId, tenantId } = req.body;
  const tenant = tenants.get(tenantId);
  if (!tenant || !tenant.getUser(userId)) {
    return res.status(401).json({ error: 'Invalid credentials' });
  }
  const token = crypto.randomBytes(32).toString('hex');
  sessions.set(token, { userId, tenantId });
  res.json({ token });
});

module.exports = app;
